from urllib.request import urlopen
from urllib.error import HTTPError
url = input()
try:
    with urlopen(url) as r:
        print("Success", r.status)
except HTTPError as e:
    if e.code == 404:
        print("No such page")
    elif e.code >= 500:
        print("Server error", e.code)
    else:
        print("Bad request", e.code)

